  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}
const parsedRows = $('Shape ready for unsuspend rows').all().map(i => i.json || {}).filter(r => !r._no_unsuspend_rows);
const trackingRows = $('Read ASB_Tracking unsuspend1').all().map(i => i.json || {});
const settings = $('Set API base URL5').first().json || {};
const api_base_url = settings.api_base_url;
const contract_id = settings.contract_id;
const skipAlreadyUnsuspended = settings.skip_already_unsuspended !== false && String(settings.skip_already_unsuspended).toLowerCase() !== 'false';

function normStatus(s) {
  return String(s ?? '').trim().toLowerCase();
}
function isSuspendedStatus(st) {
  const s = normStatus(st);
  return s === 'suspended' || s.includes('suspended');
}
function isAlreadyUnsuspended(st) {
  const s = normStatus(st);
  return s === 'unsuspended' || s === 'un suspended' || s.includes('unsuspended');
}

const trackingByCorf = new Map();
for (const r of trackingRows) {
  const corf = normCorf(r.corf);
  if (!corf) continue;
  trackingByCorf.set(corf, r);
}

const eligible_rows = [];
const seenCorf = new Set();
for (const r of parsedRows) {
  const corf = normCorf(r.corf);
  const addr = String(r.address || '').trim();
  if (!corf || !addr) continue;
  const tracked = trackingByCorf.get(corf);
  const sheetStatus = tracked ? normStatus(tracked.status) : '';
  if (skipAlreadyUnsuspended && tracked && isAlreadyUnsuspended(tracked.status)) continue;
  const cid = String((tracked && tracked.contract_id) || contract_id || '').trim();
  const key = `${cid}::${corf}`;
  if (seenCorf.has(key)) continue;
  seenCorf.add(key);
  eligible_rows.push({
    contract_id: (tracked && tracked.contract_id) || contract_id,
    uprn: r.uprn || (tracked && tracked.uprn) || null,
    address: addr,
    corf,
    pre_work_id: r.pre_work_id,
    update_sheet: !!(tracked && isSuspendedStatus(tracked.status)),
    in_asb_tracking: !!tracked,
    asb_tracking_status: sheetStatus || null,
  });
}

const addresses = eligible_rows.map(e => e.address);
const corfs = eligible_rows.map(e => e.corf).filter(Boolean);
if (!corfs.length) return [];
return [{ json: { corfs: [...new Set(corfs)], addresses: [...new Set(addresses)], contract_id, api_base_url, eligible_rows } }];

